import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

// The choisys section reads src/data/choisys-cases.json (generated by neos-cube `make cases`). These are the
// shapes it relies on; if a regenerated file breaks them, the page would draw nonsense, so fail here instead.
const data = JSON.parse(readFileSync(new URL('../src/data/choisys-cases.json', import.meta.url), 'utf8'));
const sum = list => list.reduce((a, b) => a + b, 0);

test('product case: 3 phases × 9 cells, 81 combinations × 9 products, counts that add up', () => {
  const p = data.product;
  assert.equal(p.share.length, 3);
  assert.ok(p.share.every(phase => phase.length === 9));
  assert.equal(p.after.length, 81);
  assert.ok(p.afterShare.every(row => row.length === 9 && Math.abs(sum(row) - 100) <= 0.6));
  assert.equal(sum(p.afterN), p.funnel[3]);
  assert.ok(p.afterN.every(n => n > 0), 'every combination the demo can reach has people behind it');
  assert.ok(p.funnel.every((n, i) => i === 0 || n <= p.funnel[i - 1]), 'a funnel only narrows');
  assert.ok(p.sample.every(run => run.length === 3));
});

test('hiring case: histogram covers everyone who completed; ranking ordered by similarity', () => {
  const h = data.hiring;
  assert.equal(h.histogram.length, 10);
  assert.equal(sum(h.histogram), h.funnel[2]);
  assert.ok(h.ranking.every((r, i) => i === 0 || r.similarity <= h.ranking[i - 1].similarity));
  assert.ok(h.ranking.every(r => r.similarity >= 0 && r.similarity <= 100 && r.phases.length === 3 && r.run.length === 3));
  assert.equal(h.reference.length, 3);
});
